        /// <summary>
        /// Decoding: index = context &lt;&lt; 7 | next 7 VLC bits; value = length | u_off &lt;&lt; 3 | rho &lt;&lt; 4 | emb_k &lt;&lt; 8 | emb_1 &lt;&lt; 12.
        /// </summary>
        public static readonly ushort[] Decode0 = BuildDecode(Table0), Decode1 = BuildDecode(Table1);

        static ushort[] BuildDecode(uint[] table)
        {
            var lut = new ushort[8 * 128];
            foreach (uint e in table)
            {
                int c = (int)(e & 7), rho = (int)(e >> 3 & 15), uoff = (int)(e >> 7 & 1), ek = (int)(e >> 8 & 15), e1 = (int)(e >> 12 & 15);
                int w = (int)(e >> 16 & 127), len = (int)(e >> 23);
                ushort v = (ushort)(len | uoff << 3 | rho << 4 | ek << 8 | e1 << 12);
                for (int hi = 0; hi < 128; hi += 1 << len) lut[c << 7 | hi | w] = v;
            }
            return lut;
        }
